import { isNonEmptyArray } from "../helpers";
import { RichTextType } from "../components";
import { ExistingThemes } from "../types";
import { IGatsbyImageData } from "gatsby-plugin-image";

const validLocales = ["sv", "en"] as const;
type ValidLocales = (typeof validLocales)[number];

export type TextBlock = {
  contentful_id: string;
  node_locale: ValidLocales;
  internalTitle: string;
  id: string;
  componentTheme: ExistingThemes;
  richText: RichTextType;
  image?: {
    gatsbyImageDataXs: IGatsbyImageData;
    gatsbyImageDataS: IGatsbyImageData;
    gatsbyImageDataM: IGatsbyImageData;
    gatsbyImageDataL: IGatsbyImageData;
    gatsbyImageDataCornerMobile: IGatsbyImageData;
    gatsbyImageDataCornerDesktop: IGatsbyImageData;
    description: string;
  };
  animation?: {
    url: string;
  };
};

type TextBlockStoreState = {
  sv: Array<TextBlock>;
  en: Array<TextBlock>;
};

export type ITextBlockStore = {
  populateStore(textBlocks: Array<TextBlock>): void;
  getTextBlockByContentfulId(contentfulId: string, locale?: string): TextBlock | null | undefined;
  getTextBlocksByContentfulIds(contentfulIds: Array<string>, locale?: string): Array<TextBlock>;
};

class TextBlockStore implements ITextBlockStore {
  textBlocks: TextBlockStoreState = {
    sv: [],
    en: [],
  };
  initialized = false;

  populateStore(textBlocks: Array<TextBlock>): void {
    if (!isNonEmptyArray(textBlocks) || this.initialized) {
      return;
    }

    textBlocks.forEach((textBlock) => {
      if (this.textBlocks[textBlock.node_locale] instanceof Array) {
        this.textBlocks[textBlock.node_locale].push(textBlock);
      } else {
        this.textBlocks[textBlock.node_locale] = [textBlock];
      }
    });
    this.initialized = true;
  }

  getTextBlockByContentfulId(contentfulId: string, locale: ValidLocales) {
    return this.initialized
      ? this.textBlocks[locale].find((textBlock) => textBlock.contentful_id === contentfulId)
      : null;
  }

  getTextBlocksByContentfulIds(contentfulIds: Array<string>, locale: ValidLocales) {
    return this.initialized
      ? this.textBlocks[locale].filter((textBlock) => contentfulIds.includes(textBlock.contentful_id))
      : [];
  }

  isValidLocale(locale: string): locale is ValidLocales {
    return validLocales.includes(locale as ValidLocales);
  }
}

const store = new TextBlockStore();
export default store;
