import { ScheduleService } from "@/core/services/schedule-service";
import ShowStore from "@/core/stores/show-store";
import DateHelper, { createDate } from "@/core/helpers/date-helper";
import { sortIndexComparer, isNonEmptyArray } from "@/core/helpers/array-helper";
import { Event, ShowProps } from "@/core/components/primitives/calendar/types/calendar-types";
import { EventAndTextBlock, ScheduleType, Tag } from "../types";
import { ContentfulEvent, ContentfulSchedule } from "@parksandresorts/webapiproxy-types";
import TextBlockStore from "@/core/stores/text-block-store";

export type IScheduleStore = {
  getEventsForShowIds: (
    showIdsArray?: Array<string>,
    date?: Date,
    disableSorting?: boolean,
  ) => Promise<Array<ShowProps>>;
  getEventsForShowId: (showId: string) => Promise<Array<Event>>;
  getEventsForDate: (date: Date) => Promise<Array<Event>>;
  getEventsForDates: () => Promise<Array<Event>>;
  getEventsFromDate: (date: Date) => Promise<Array<Event>>;
  getEventsByShowForDate: (date: Date) => Promise<Array<ShowProps>>;
  getScheduleForShow: (showId: string) => Promise<{
    events: Event[];
  }>;
  getEventsForShowForDate: (showId: string, date: Date) => Promise<Event[]>;
  getSchedulesForTypes: (types: Array<ScheduleType>) => Promise<Array<ContentfulSchedule>>;
  getTextBlocksForPurchaseFlow: (locale: string) => Promise<Array<EventAndTextBlock>>;
};

type ShowMap = { [key: string]: ShowProps };

class ScheduleStore implements IScheduleStore {
  eventInitialized: boolean;
  events: Event[];

  schedules: Map<
    ScheduleType,
    {
      initialized: boolean;
      schedules: Array<ContentfulSchedule>;
    }
  >;

  constructor() {
    this.eventInitialized = false;
    this.events = [];
    this.schedules = new Map<
      ScheduleType,
      {
        initialized: boolean;
        schedules: Array<ContentfulSchedule>;
      }
    >();
  }

  private async initEventStore() {
    if (this.eventInitialized) {
      return;
    }

    try {
      const response = await ScheduleService.getSchedules(["Event"]);

      if (response.success) {
        this.events = [];
        const schedules = response.response ?? [];

        schedules.forEach((schedule) => {
          if (schedule.events instanceof Array && schedule.events.length) {
            const show = ShowStore.getShowByShowId(schedule.externalEntry?.externalEntryId);

            const eventsWithDate: Event[] = schedule.events?.map((event) => ({
              title: show ? show.title : event.title,
              startDateAndTime: createDate(event.startDateAndTime),
              endDateAndTime: event.endDateAndTime ? createDate(event.endDateAndTime) : undefined,
              cancelled: event.cancelled,
              cancelledText: event.cancelledText,
              id: event.id,
              description: event.description,
              showId: event.externalEntry ? event.externalEntry.externalEntryId : undefined,
            }));

            this.events.push(...eventsWithDate);
          }
        });

        this.events.sort(this.sortEventByDate);
        this.eventInitialized = true;
        return;
      } else {
        throw new Error("Error fetching schedules: response is not successful");
      }
    } catch (err) {
      throw new Error("Error fetching schedules: " + err);
    }
  }

  private async safeInitEventStore() {
    try {
      await this.initEventStore();
    } catch (err) {
      console.error("Error initializing store: ", err);
    }
  }

  private async getSchedulesForType(scheduleType: ScheduleType) {
    const response = await ScheduleService.getSchedules([scheduleType]);

    if (response.success) {
      return response.response;
    } else {
      throw new Error("Error fetching schedules: response is not successful");
    }
  }

  private async safeInitScheduleStore(scheduleTypes: Array<ScheduleType>) {
    const schedulesPerType = scheduleTypes.map(async (type) => {
      if (this.schedules.has(type) && this.schedules.get(type)?.initialized) {
        return;
      }

      const schedules = (await this.getSchedulesForType(type)) ?? [];

      this.schedules.set(type, {
        initialized: true,
        schedules: schedules ?? [],
      });
    });

    await Promise.all(schedulesPerType);
  }

  async getEventsForShowIds(
    showIdsArray: Array<string> = [],
    date = DateHelper.getStartOfYearDate(),
    disableSorting = false,
  ) {
    const response = await this.getEventsFromDate(date);
    const showMapFromEvents = this.reduceEventsToMap(response);
    const filteredShows: Array<ShowProps> = [];
    for (const key in showMapFromEvents) {
      if (showIdsArray.includes(key)) {
        showMapFromEvents[key].events.sort(this.sortEventByDate);
        filteredShows.push(showMapFromEvents[key]);
      }
    }
    if (!disableSorting) {
      this.sortShowsByFirstEvent(filteredShows);
    }
    return filteredShows;
  }

  async getEventsForShowId(showId: string) {
    await this.safeInitEventStore();
    return this.events instanceof Array && this.events.length
      ? this.events.filter((event) => event.showId === showId)
      : [];
  }

  async getEventsForDate(date: Date) {
    if (!DateHelper.isDateValid(date)) {
      return Promise.reject("Faulty parameter: date");
    }

    await this.safeInitEventStore();
    return this.events instanceof Array && this.events.length
      ? this.events.filter((event) => DateHelper.isEqualYYYYMMDD(event.startDateAndTime, date))
      : [];
  }

  async getEventsForDates() {
    await this.safeInitEventStore();
    return this.events;
  }

  async getEventsFromDate(date: Date) {
    if (!DateHelper.isDateValid(date)) {
      throw new Error("Faulty parameter: date");
    }

    await this.safeInitEventStore();
    return this.events instanceof Array && this.events.length
      ? this.events.filter((event) => event.startDateAndTime > date)
      : [];
  }

  async getEventsByShowForDate(date: Date) {
    await this.safeInitEventStore();
    const events = await this.getEventsForDate(date);
    const showMap = {} as ShowMap;
    events.forEach((event) => {
      if (event.showId && showMap[event.showId]) {
        showMap[event.showId].events.push(event);
      } else {
        const show = ShowStore.getShowByShowId(event.showId);
        if (show && event.showId) {
          showMap[event.showId] = {
            events: [event],
            ...show,
          };
        }
      }
    });

    return Object.values(showMap).sort(sortIndexComparer);
  }

  private reduceEventsToMap(events: Array<Event>, tag?: Tag) {
    const showMap = events.reduce((showMap, event) => {
      const show = ShowStore.getShowByShowId(event.showId);

      if (!show) {
        return showMap;
      }

      if (tag && tag.title) {
        if (!isNonEmptyArray(show.tags)) {
          return showMap;
        }

        if (show.tags && !show.tags.find((t) => t.title === tag.title)) {
          return showMap;
        }
      }

      if (showMap[show.contentful_id]) {
        showMap[show.contentful_id].events.push(event);
      } else {
        showMap[show.contentful_id] = {
          ...show,
          events: [event],
        };
      }

      return showMap;
    }, {} as ShowMap);

    return showMap;
  }

  private sortEventByDate(a: Event, b: Event) {
    if (a.startDateAndTime < b.startDateAndTime) {
      return -1;
    }
    if (a.startDateAndTime > b.startDateAndTime) {
      return 1;
    }

    return 0;
  }

  private sortEventsAndTransformToArray(showMap: ShowMap) {
    const shows: Array<ShowProps> = [];
    for (const show of Object.values(showMap)) {
      show.events.sort(this.sortEventByDate);
      shows.push(show);
    }

    return shows;
  }

  private sortShowsByFirstEvent(showsArray: Array<ShowProps>) {
    if (!(showsArray instanceof Array && showsArray.length > 0)) {
      return;
    }

    showsArray.sort((a, b) => {
      if (a.events[0].startDateAndTime < b.events[0].startDateAndTime) {
        return -1;
      }
      if (a.events[0].startDateAndTime > b.events[0].startDateAndTime) {
        return 1;
      }

      return 0;
    });
  }

  groupEventsByDate(events: Array<Event>, tag: Tag | undefined): Array<ShowProps> {
    const showMap = this.reduceEventsToMap(events, tag);
    const shows = this.sortEventsAndTransformToArray(showMap);
    this.sortShowsByFirstEvent(shows);
    return shows;
  }

  sortEventsAndGetShowData(events: Array<Event>, tag: Tag | undefined): Array<ShowProps> {
    const sortedEvents = [...events].sort(this.sortEventByDate);
    const shows = sortedEvents
      .map((event) => {
        const show = ShowStore.getShowByShowId(event.showId);
        return show ? { ...show, events: [event] } : null;
      })
      .filter((show): show is NonNullable<typeof show> => show !== null);

    if (tag && tag.title) {
      return shows.filter((show) => {
        if (!show.tags) {
          return false;
        }
        return show.tags.some((t) => t.title === tag.title);
      });
    }
    return shows;
  }

  async getShowsForDateByTag(date: Date, tag: Tag | undefined, groupEvents = true) {
    const events = await this.getEventsForDate(date);
    if (groupEvents) {
      return this.groupEventsByDate(events, tag);
    }
    return this.sortEventsAndGetShowData(events, tag);
  }

  async getShowsFromDateByTag(date: Date, tag: Tag | undefined, groupEvents = true) {
    const events = await this.getEventsFromDate(date);
    if (groupEvents) {
      return this.groupEventsByDate(events, tag);
    }
    return this.sortEventsAndGetShowData(events, tag);
  }

  async getScheduleForShow(showId: string) {
    await this.safeInitEventStore();

    const eventsForShow = this.events.filter((event) => event.showId === showId);
    return {
      events: eventsForShow,
    };
  }

  async getEventsForShowForDate(showId: string, date: Date) {
    await this.safeInitEventStore();

    const show = await this.getScheduleForShow(showId);
    if (show && show.events instanceof Array && show.events.length > 0) {
      return show.events.filter((event) => DateHelper.isEqualYYYYMMDD(event.startDateAndTime, date));
    }
    return Promise.resolve([]);
  }

  async getSchedulesForTypes(types: Array<ScheduleType>) {
    await this.safeInitScheduleStore(types);
    return types.flatMap((type) => {
      const scheduleObj = this.schedules.get(type);
      if (!scheduleObj || !scheduleObj.initialized) return [];
      return scheduleObj.schedules;
    });
  }

  async getTextBlocksForPurchaseFlow(locale: string) {
    const schedules = await this.getSchedulesForTypes(["PurchaseFlowCalendarEvent"]);

    const events = schedules
      .flatMap((schedule) => schedule.events)
      .filter((event) => event !== undefined)
      .map((event) => event as ContentfulEvent);

    const textBlockIds = events
      .map((event) => event?.externalEntry?.externalEntryId)
      .filter((id) => id !== undefined)
      .map((id) => id as string);

    const textBlocks = TextBlockStore.getTextBlocksByContentfulIds(
      textBlockIds,
      TextBlockStore.isValidLocale(locale) ? locale : "sv",
    );

    return events
      .map((event) => {
        const textBlock = textBlocks.find((block) => block.contentful_id === event?.externalEntry?.externalEntryId);
        return {
          event,
          textBlock,
        };
      })
      .filter((eventWithTextBlock) => eventWithTextBlock.textBlock !== undefined)
      .map((eventWithTextBlock) => eventWithTextBlock as EventAndTextBlock);
  }
}

const store = new ScheduleStore();
export default store;
