// @ts-strict-ignore
import { IGatsbyImageData } from "gatsby-plugin-image";
import { isNonEmptyArray } from "@/core/helpers/array-helper";
import LanguageHelper from "@/core/helpers/language-helper";
import { Tag } from "../types";

export type ShowNode = {
  contentful_id: string;
  node_locale: "sv" | "en";
  internalTitle: string;
  id: string;
  sortIndex?: number;
  preHeading?: string;
  title: string;
  preamble?: {
    preamble: string;
  };
  label?: string;
  labelComponentTheme?: string;
  shortDescriptionInList?: string;
  pageLink?: {
    slug: string;
  };
  imageInList?: {
    file: {
      url: string;
    };
    gatsbyImageData?: IGatsbyImageData;
  };
  tags?: Array<Tag>;
  length?: string;
  location?: string;
  product?: {
    contentful_id: string;
    productPageLink: {
      slug: string;
    };
  };
  mapLink?: {
    id: string;
    title: string;
    smallDeviceTitle: string;
    internalLink: {
      slug: string;
    };
    externalUrl: string;
    openInNewTab: boolean;
    image: {
      file: {
        url: string;
      };
    };
    asset: {
      file: {
        url: string;
      };
    };
    icon: string;
  };
  calendarText?: {
    calendarText: string;
  };
  calendarLink?: string;
  /** Custom date text to display instead of event time. */
  customDateText?: string;
  /** Custom time to append to the custom date text. */
  customDateTime?: string;
  /** If true, only show the custom text(s) and hide the event date. */
  hideEventDateAndOnlyShowCustomText?: boolean;
  showInPurchaseFlow?: boolean;
  openEntireDay?: boolean;
  showProductDescriptionTextInPurchaseFlow?: string;
  image?: {
    file: {
      url: string;
    };
    gatsbyImageData?: IGatsbyImageData;
  };
  showPageLink?: {
    slug: string;
  };
};

export type Show = {
  node: ShowNode;
};

type ShowsData = {
  sv: Array<ShowNode>;
  en: Array<ShowNode>;
};

export type IShowStore = {
  populateStore(shows: Array<Show>): void;
  getShowByShowId(showId: string, locale?: string): ShowNode | null | undefined;
  getShowsForPurchaseFlow(locale?: string): Array<ShowNode>;
};

class ShowStore implements IShowStore {
  shows: ShowsData = {
    sv: [],
    en: [],
  };
  initialized = false;

  populateStore(shows: Array<Show>): void {
    if (!isNonEmptyArray(shows) || this.initialized) {
      return;
    }

    shows.forEach((show) => {
      if (this.shows[show.node.node_locale] instanceof Array) {
        this.shows[show.node.node_locale].push(show.node);
      } else {
        this.shows[show.node.node_locale] = [show.node];
      }
    });
    this.initialized = true;
  }

  getShowByShowId(showId?: string, locale = LanguageHelper.getCurrentLocale()) {
    return this.initialized
      ? (this.shows[locale] as Array<ShowNode>)?.find((show) => show.contentful_id === showId)
      : null;
  }

  getShowsForPurchaseFlow(locale = LanguageHelper.getCurrentLocale()) {
    return this.initialized
      ? (this.shows[locale] as Array<ShowNode>)?.filter(
          (show) =>
            show.internalTitle &&
            show.internalTitle.toLowerCase().indexOf("graph") < 0 &&
            show.showInPurchaseFlow === true,
        )
      : [];
  }
}

const store = new ShowStore();
export default store;
