import ServiceHelper from "@/core/services/service-helper";
import SessionStorageHelper from "@/core/helpers/session-storage-helper";
import { createDate } from "@/core/helpers/date-helper";
import { ContentfulScheduleIEnumerableApiResponse } from "@parksandresorts/webapiproxy-types";
import { createQueryParams } from "@/core/helpers/http-helpers";
import { ScheduleType } from "../types";

export const ScheduleService = {
  async getSchedules(scheduleTypes: Array<ScheduleType>): Promise<ContentfulScheduleIEnumerableApiResponse> {
    const key = `ScheduleService-getSchedules-${scheduleTypes.join("-")}`;
    const sessionStorageValue: ContentfulScheduleIEnumerableApiResponse = SessionStorageHelper.getItem(key);
    if (sessionStorageValue) {
      return Promise.resolve(sessionStorageValue);
    }

    const params = scheduleTypes.map((scheduleType) => ({ key: "scheduleTypes", value: scheduleType }));
    const path = `/schedule/v2${createQueryParams(params)}`;

    const response = await ServiceHelper.fetchGet<ContentfulScheduleIEnumerableApiResponse>(path);
    const timeStampDate = createDate();
    timeStampDate.setMinutes(timeStampDate.getMinutes() + 5);
    SessionStorageHelper.setItem(key, response, timeStampDate.getTime());
    return response;
  },

  getLocationSchedule() {
    const key = "ScheduleService-getLocationSchedule";
    const response = SessionStorageHelper.getItem(key);
    if (response) {
      return Promise.resolve(response);
    }

    return ServiceHelper.fetchGet("/schedule/locationopeninghours")
      .then((response) => {
        const timeStampDate = createDate();
        timeStampDate.setMinutes(timeStampDate.getMinutes() + 5);
        SessionStorageHelper.setItem(key, response, timeStampDate.getTime());
        return response;
      })
      .catch((err) => {
        console.error("Failed while fetching location schedule: ", err);
      });
  },

  getDailyInformation() {
    const key = "ScheduleService-getDailyInformation";
    const response = SessionStorageHelper.getItem(key);
    if (response) {
      return Promise.resolve(response);
    }

    return ServiceHelper.fetchGet("/schedule/dailyinformation").then((response) => {
      const timeStampDate = createDate();
      timeStampDate.setMinutes(timeStampDate.getMinutes() + 5);
      SessionStorageHelper.setItem(key, response, timeStampDate.getTime());

      return response;
    });
  },
};
